PRAGMA application_id=1347895620;
PRAGMA user_version=1;
PRAGMA foreign_keys=ON;
CREATE TABLE datasets(id TEXT PRIMARY KEY,name TEXT NOT NULL,url TEXT NOT NULL,license TEXT,updated_at TEXT,retrieved_at TEXT,sha256 TEXT);
CREATE TABLE source_snapshots(id TEXT PRIMARY KEY,source TEXT NOT NULL REFERENCES datasets(id),scope_id TEXT,updated_at TEXT,retrieved_at TEXT,sha256 TEXT);
CREATE TABLE oblasts(id TEXT PRIMARY KEY,name TEXT NOT NULL,norm TEXT NOT NULL);
CREATE TABLE districts(id TEXT PRIMARY KEY,oblast_id TEXT NOT NULL REFERENCES oblasts(id),name TEXT NOT NULL,norm TEXT NOT NULL);
CREATE TABLE communities(id TEXT PRIMARY KEY,oblast_id TEXT NOT NULL REFERENCES oblasts(id),district_id TEXT REFERENCES districts(id),name TEXT NOT NULL,norm TEXT NOT NULL);
CREATE TABLE settlements(id TEXT PRIMARY KEY,oblast_id TEXT NOT NULL REFERENCES oblasts(id),district_id TEXT REFERENCES districts(id),community_id TEXT REFERENCES communities(id),name TEXT NOT NULL,norm TEXT NOT NULL,kind TEXT NOT NULL);
CREATE INDEX settlements_parent_name ON settlements(oblast_id,district_id,community_id,norm);
CREATE TABLE city_districts(id TEXT PRIMARY KEY,settlement_id TEXT NOT NULL REFERENCES settlements(id),name TEXT NOT NULL,norm TEXT NOT NULL);
CREATE TABLE settlement_names(settlement_id TEXT NOT NULL REFERENCES settlements(id),name TEXT NOT NULL,norm TEXT NOT NULL,source TEXT NOT NULL REFERENCES datasets(id),relation TEXT NOT NULL,PRIMARY KEY(settlement_id,norm,source));
CREATE INDEX districts_oblast ON districts(oblast_id,norm);
CREATE INDEX communities_parent ON communities(oblast_id,district_id,norm);
CREATE TABLE streets(id INTEGER PRIMARY KEY,settlement_id TEXT NOT NULL REFERENCES settlements(id),name TEXT NOT NULL,norm TEXT NOT NULL,rank INTEGER NOT NULL);
CREATE INDEX streets_parent_name ON streets(settlement_id,norm);
CREATE TABLE street_names(street_id INTEGER NOT NULL REFERENCES streets(id),settlement_id TEXT NOT NULL REFERENCES settlements(id),name TEXT NOT NULL,norm TEXT NOT NULL,source TEXT NOT NULL REFERENCES datasets(id),relation TEXT NOT NULL,PRIMARY KEY(street_id,norm,source));
CREATE INDEX street_names_lookup ON street_names(settlement_id,norm,street_id);
CREATE TABLE houses(id INTEGER PRIMARY KEY,street_id INTEGER NOT NULL REFERENCES streets(id),number TEXT NOT NULL,number_norm TEXT NOT NULL,building TEXT NOT NULL,building_norm TEXT NOT NULL,postcode TEXT,rank INTEGER NOT NULL,UNIQUE(street_id,number_norm,building_norm));
CREATE INDEX houses_parent_number ON houses(street_id,number_norm,building_norm);
CREATE TABLE source_records(source TEXT NOT NULL REFERENCES datasets(id),kind TEXT NOT NULL,entity_id NOT NULL,native_id TEXT,record_key TEXT,updated_at TEXT,snapshot_id TEXT REFERENCES source_snapshots(id));
CREATE INDEX source_entity ON source_records(kind,entity_id);
CREATE TABLE source_localities(source TEXT NOT NULL,source_key TEXT NOT NULL,settlement_id TEXT REFERENCES settlements(id),oblast_name TEXT,district_name TEXT,locality_name TEXT,reason TEXT,PRIMARY KEY(source,source_key));
CREATE TABLE coverage(settlement_id TEXT NOT NULL REFERENCES settlements(id),source TEXT NOT NULL,status TEXT NOT NULL,streets INTEGER NOT NULL,houses INTEGER NOT NULL,PRIMARY KEY(settlement_id,source));
CREATE TABLE metadata(key TEXT PRIMARY KEY,value TEXT NOT NULL);
